  );
};

import type { Editor } from "@tiptap/react";
import { useState, useCallback } from "react";

import { chainFocus } from "../lib/commands";
import {
  BubbleButton,
  BubbleDropdown,
  BubbleDropdownDivider,
  ColorSwatch,
  DropdownOverlay,
} from "../ui";
import { useEditorState, shallowEqual } from "./utils";

type SwatchType = "text" | "highlight";

interface RecentColor {
  type: SwatchType;
  color: string;
  label: string;
}

const RECENT_KEY = "editorcn-block-editor-recent-colors";
const RECENT_LIMIT = 10;

const ColorGroup = ({
  title,
  children,
  className,
}: {
  title: string;
  children: React.ReactNode;
  className: string;
}) => (
  <div className="block-editor-color-section flex flex-col gap-2">
    <span className="block-editor-color-label px-0.5 text-xs leading-none font-bold text-muted-foreground">
      {title}
    </span>
    <div className={className}>{children}</div>
  </div>
);

const storage = {
  get(): RecentColor[] {
    if (typeof window === "undefined") {
      return [];
    }
    try {
      const raw = window.localStorage.getItem(RECENT_KEY);
      if (!raw) {
        return [];
      }
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed.slice(0, RECENT_LIMIT) : [];
    } catch {
      return [];
    }
  },
  set(recent: RecentColor[]): void {
    try {
      window.localStorage.setItem(RECENT_KEY, JSON.stringify(recent));
    } catch {
      // Silently fail if localStorage is disabled or full
    }
  },
};

const TEXT_COLORS = [
  { color: "#0f172a", label: "Foreground" },
  { color: "#ef4444", label: "Red" },
  { color: "#f97316", label: "Orange" },
  { color: "#f59e0b", label: "Amber" },
  { color: "#22c55e", label: "Green" },
  { color: "#0ea5e9", label: "Sky" },
  { color: "#3b82f6", label: "Blue" },
  { color: "#6366f1", label: "Indigo" },
  { color: "#a855f7", label: "Purple" },
  { color: "#ec4899", label: "Pink" },
] as const;

const HIGHLIGHT_COLORS = [
  { color: "#fef08a", label: "Yellow" },
  { color: "#fed7aa", label: "Orange" },
  { color: "#fecaca", label: "Red" },
  { color: "#fbcfe8", label: "Pink" },
  { color: "#e9d5ff", label: "Purple" },
  { color: "#ddd6fe", label: "Violet" },
  { color: "#bfdbfe", label: "Blue" },
  { color: "#a5f3fc", label: "Cyan" },
  { color: "#99f6e4", label: "Teal" },
  { color: "#bbf7d0", label: "Green" },
] as const;

export const ColorSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const [recent, setRecent] = useState<RecentColor[]>(storage.get);

  const { highlightColor, textColor } = useEditorState(
    editor,
    (ed) => ({
      highlightColor: ed.isActive("highlight")
        ? (ed.getAttributes("highlight").color as string | undefined)
        : undefined,
      textColor: ed.isActive("textStyle")
        ? (ed.getAttributes("textStyle").color as string | undefined)
        : undefined,
    }),
    shallowEqual
  );

  const hasColor = editor.extensionManager.extensions.some(
    (ext) => ext.name === "color"
  );
  const hasHighlight = editor.extensionManager.extensions.some(
    (ext) => ext.name === "highlight"
  );

  const rememberColor = useCallback(
    (type: SwatchType, color: string, label: string) => {
      setRecent((prev) => {
        const next = [
          { color, label, type },
          ...prev.filter(
            (item) => !(item.type === type && item.color === color)
          ),
        ].slice(0, RECENT_LIMIT);
        storage.set(next);
        return next;
      });
    },
    []
  );

  const selectColor = useCallback(
    (type: SwatchType, color: string, label: string) => {
      rememberColor(type, color, label);

      if (type === "text") {
        if (textColor === color) {
          chainFocus(editor).unsetColor().run();
        } else {
          chainFocus(editor).setColor(color).run();
        }
      } else if (highlightColor === color) {
        chainFocus(editor).unsetHighlight().run();
      } else {
        chainFocus(editor).setHighlight({ color }).run();
      }
    },
    [editor, textColor, highlightColor, rememberColor]
  );

  if (!hasColor && !hasHighlight) {
    return null;
  }

  return (
    <div style={{ position: "relative" }}>
      <BubbleButton
        active={Boolean(textColor || highlightColor)}
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => setOpen(!open)}
        title="Text color"
      >
        <span className="block-editor-color-icon flex size-4 items-center justify-center [&_svg]:size-full">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M4 20h16" />
            <path d="m6 16 6-12 6 12" />
            <path d="M8 12h8" />
          </svg>
        </span>
      </BubbleButton>

      {open && (
        <>
          <DropdownOverlay
            onClick={() => setOpen(false)}
            onKeyDown={(e) => e.key === "Escape" && setOpen(false)}
          />
          <BubbleDropdown className="block-editor-bubble-dropdown--color min-w-auto p-2 [&_.block-editor-bubble-dropdown-divider]:mx-0 [&_.block-editor-bubble-dropdown-divider]:mt-2 [&_.block-editor-bubble-dropdown-divider]:mb-1.5">
            {recent.length > 0 && (
              <ColorGroup
                title="Recently Used"
                className="block-editor-color-recent flex flex-wrap justify-center gap-1.5"
              >
                {recent.map((item) => (
                  <ColorSwatch
                    key={`${item.type}-${item.color}`}
                    variant={item.type}
                    color={item.color}
                    label={item.label}
                    active={
                      item.type === "text"
                        ? textColor === item.color
                        : highlightColor === item.color
                    }
                    onSelect={() =>
                      selectColor(item.type, item.color, item.label)
                    }
                  />
                ))}
              </ColorGroup>
            )}

            {hasColor && (
              <>
                {recent.length > 0 && <BubbleDropdownDivider />}
                <ColorGroup
                  title="Text Color"
                  className="block-editor-color-grid grid grid-cols-[repeat(5,1.5rem)] justify-center gap-1.5"
                >
                  {TEXT_COLORS.map((item) => (
                    <ColorSwatch
                      key={item.color}
                      variant="text"
                      color={item.color}
                      label={item.label}
                      active={textColor === item.color}
                      onSelect={() =>
                        selectColor("text", item.color, item.label)
                      }
                    />
                  ))}
                </ColorGroup>
              </>
            )}

            {hasHighlight && (
              <>
                {(recent.length > 0 || hasColor) && <BubbleDropdownDivider />}
                <ColorGroup
                  title="Highlight Color"
                  className="block-editor-color-grid grid grid-cols-[repeat(5,1.5rem)] justify-center gap-1.5"
                >
                  {HIGHLIGHT_COLORS.map((item) => (
                    <ColorSwatch
                      key={item.color}
                      variant="highlight"
                      color={item.color}
                      label={item.label}
                      active={highlightColor === item.color}
                      onSelect={() =>
                        selectColor("highlight", item.color, item.label)
                      }
                    />
                  ))}
                </ColorGroup>
              </>
            )}
          </BubbleDropdown>
        </>
      )}
    </div>
  );
};

import type { Editor } from "@tiptap/react";
import { useState, useRef, useCallback, useEffect } from "react";

import { DEFAULT_ICONS } from "../icons";
import {
  BubbleButton,
  BubbleDropdown,
  BubbleDropdownIcon,
  BubbleDropdownItem,
  DropdownOverlay,
} from "../ui";

interface LinkableChain {
  extendMarkRange(type: string): LinkableChain;
  run(): boolean;
  setLink(options: { href: string }): LinkableChain;
  unsetLink(): LinkableChain;
}

export const LinkSelector = ({ editor }: { editor: Editor }) => {
  const [open, setOpen] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const [{ isLink, linkUrl }, setLinkState] = useState(() => ({
    isLink: editor.isActive("link"),
    linkUrl: editor.getAttributes("link").href || "",
  }));

  useEffect(() => {
    const update = () => {
      setLinkState({
        isLink: editor.isActive("link"),
        linkUrl: editor.getAttributes("link").href || "",
      });
    };
    editor.on("selectionUpdate", update);
    editor.on("transaction", update);
    return () => {
      editor.off("selectionUpdate", update);
      editor.off("transaction", update);
    };
  }, [editor]);

  const handleSubmit = useCallback(
    (evt: React.FormEvent) => {
      evt.preventDefault();
      let url = inputRef.current?.value?.trim();
      if (!url) {
        return;
      }
      if (!/^https?:\/\//i.test(url)) {
        url = `https://${url}`;
      }
      (editor.chain().focus() as unknown as LinkableChain)
        .extendMarkRange("link")
        .setLink({ href: url })
        .run();
      setOpen(false);
    },
    [editor]
  );

  const handleUnlink = useCallback(() => {
    (editor.chain().focus() as unknown as LinkableChain).unsetLink().run();
    setOpen(false);
  }, [editor]);

  return (
    <div style={{ position: "relative" }}>
      <BubbleButton
        active={isLink}
        onMouseDown={(e) => e.preventDefault()}
        onClick={() => setOpen(!open)}
        title="Link"
      >
        {DEFAULT_ICONS.linkIcon}
      </BubbleButton>
      {open && (
        <>
          <DropdownOverlay
            onClick={() => setOpen(false)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                setOpen(false);
              }
            }}
          />
          <BubbleDropdown style={{ left: "auto", minWidth: "220px", right: 0 }}>
            <form
              className="block-editor-link-form flex flex-col gap-2 p-1"
              onSubmit={handleSubmit}
            >
              <input
                ref={inputRef}
                type="text"
                className="block-editor-link-input h-8 w-full rounded-sm border border-border bg-transparent px-2 text-[0.8125rem] [font-family:inherit] text-popover-foreground outline-none [transition:border-color_150ms_ease-out,box-shadow_150ms_ease-out] placeholder:text-muted-foreground focus:border-ring focus:shadow-[0_0_0_2px_color-mix(in_srgb,var(--ring)_20%,transparent)]"
                placeholder="Paste a link..."
                defaultValue={linkUrl}
                autoFocus
              />
              <div className="block-editor-link-actions flex gap-1">
                {isLink && (
                  <BubbleDropdownItem
                    danger
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={handleUnlink}
                    style={{ justifyContent: "center" }}
                  >
                    <BubbleDropdownIcon>
                      {DEFAULT_ICONS.unlinkIcon}
                    </BubbleDropdownIcon>
                    <span>Remove</span>
                  </BubbleDropdownItem>
                )}
                <BubbleDropdownItem
                  onMouseDown={(e) => e.preventDefault()}
                  type="submit"
                  style={{ justifyContent: "center" }}
                >
                  <BubbleDropdownIcon>
                    {DEFAULT_ICONS.checkIcon}
                  </BubbleDropdownIcon>
                  <span>{isLink ? "Update" : "Add"}</span>
                </BubbleDropdownItem>
              </div>
            </form>
          </BubbleDropdown>
        </>
      )}
    </div>
  );
};

